import { useState } from "react";
import "../styles/tokens.css";
import "./Stepper.css";

const clamp = (n, min, max) => Math.min(max, Math.max(min, n));

/**
 * Picks a whole number from 0 to 10 by stepping it down or up.
 * Works controlled (`value` + `onChange`) or uncontrolled (`defaultValue`).
 */
export function Stepper({
  value,
  defaultValue = 1,
  onChange,
  min = 0,
  max = 10,
  label = "Value",
  className,
  ...rest
}) {
  const [internal, setInternal] = useState(() => clamp(defaultValue, min, max));
  const isControlled = value !== undefined;
  const current = clamp(isControlled ? value : internal, min, max);

  const set = (next) => {
    const clamped = clamp(next, min, max);
    if (clamped === current) return;
    if (!isControlled) setInternal(clamped);
    onChange?.(clamped);
  };

  const onKeyDown = (event) => {
    const keys = {
      ArrowUp: current + 1,
      ArrowRight: current + 1,
      ArrowDown: current - 1,
      ArrowLeft: current - 1,
      PageUp: current + 5,
      PageDown: current - 5,
      Home: min,
      End: max,
    };
    if (event.key in keys) {
      event.preventDefault();
      set(keys[event.key]);
    }
  };

  return (
    <div
      {...rest}
      className={["stepper", className].filter(Boolean).join(" ")}
      role="spinbutton"
      tabIndex={0}
      aria-label={label}
      aria-valuenow={current}
      aria-valuemin={min}
      aria-valuemax={max}
      onKeyDown={onKeyDown}
    >
      <button
        type="button"
        className="stepper__button"
        tabIndex={-1}
        aria-label={`Decrease ${label}`}
        disabled={current <= min}
        onClick={() => set(current - 1)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar stepper__bar--h" />
        </span>
      </button>
      <span className="stepper__value" aria-hidden="true">
        {current}
      </span>
      <button
        type="button"
        className="stepper__button"
        tabIndex={-1}
        aria-label={`Increase ${label}`}
        disabled={current >= max}
        onClick={() => set(current + 1)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar stepper__bar--h" />
          <span className="stepper__bar stepper__bar--v" />
        </span>
      </button>
    </div>
  );
}

export default Stepper;

