import { useState } from "react";
import "../styles/tokens.css";
import "./Stepper.css";

// Picks a whole number from min to max (0–10 by default) by stepping it down or up.
// Follows the WAI-ARIA spinbutton pattern: the value is the focusable spinbutton,
// and the − / + buttons are pointer targets kept out of the tab order.
export function Stepper({
  value,
  defaultValue = 1,
  onChange,
  min = 0,
  max = 10,
  label = "Value",
  className,
  ...rest
}) {
  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue);
  const current = clamp(isControlled ? value : internalValue, min, max);

  const setValue = (next) => {
    const clamped = clamp(next, min, max);
    if (clamped === current) return;
    if (!isControlled) setInternalValue(clamped);
    onChange?.(clamped);
  };

  const handleKeyDown = (event) => {
    const keys = {
      ArrowUp: current + 1,
      ArrowRight: current + 1,
      ArrowDown: current - 1,
      ArrowLeft: current - 1,
      PageUp: current + 5,
      PageDown: current - 5,
      Home: min,
      End: max,
    };
    if (event.key in keys) {
      event.preventDefault();
      setValue(keys[event.key]);
    }
  };

  return (
    <div className={["stepper", className].filter(Boolean).join(" ")} {...rest}>
      <button
        type="button"
        className="stepper__button"
        tabIndex={-1}
        aria-label={`Decrease ${label}`}
        disabled={current <= min}
        onClick={() => setValue(current - 1)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar stepper__bar--horizontal" />
        </span>
      </button>
      <span
        className="stepper__value"
        role="spinbutton"
        tabIndex={0}
        aria-label={label}
        aria-valuenow={current}
        aria-valuemin={min}
        aria-valuemax={max}
        onKeyDown={handleKeyDown}
      >
        {current}
      </span>
      <button
        type="button"
        className="stepper__button"
        tabIndex={-1}
        aria-label={`Increase ${label}`}
        disabled={current >= max}
        onClick={() => setValue(current + 1)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar stepper__bar--horizontal" />
          <span className="stepper__bar stepper__bar--vertical" />
        </span>
      </button>
    </div>
  );
}

function clamp(n, min, max) {
  return Math.min(max, Math.max(min, Math.round(Number(n) || 0)));
}

export default Stepper;

