import { useState } from "react";
import "./Stepper.css";

const clamp = (n, min, max) => Math.min(max, Math.max(min, n));

/**
 * Picks a whole number from 0 to 10 by stepping it down or up.
 *
 * Works controlled (`value` + `onChange`) or uncontrolled (`defaultValue`).
 * The root is the focusable spinbutton: Arrow Up/Right and Page Up step up,
 * Arrow Down/Left and Page Down step down, Home/End jump to min/max.
 */
export function Stepper({
  value,
  defaultValue = 1,
  onChange,
  min = 0,
  max = 10,
  step = 1,
  disabled = false,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...rest
}) {
  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(() => clamp(defaultValue, min, max));
  const current = clamp(isControlled ? Number(value) : internal, min, max);

  const set = (next) => {
    const clamped = clamp(next, min, max);
    if (clamped === current || disabled) return;
    if (!isControlled) setInternal(clamped);
    onChange?.(clamped);
  };

  const handleKeyDown = (event) => {
    const actions = {
      ArrowUp: () => set(current + step),
      ArrowRight: () => set(current + step),
      PageUp: () => set(current + step),
      ArrowDown: () => set(current - step),
      ArrowLeft: () => set(current - step),
      PageDown: () => set(current - step),
      Home: () => set(min),
      End: () => set(max),
    };
    const action = actions[event.key];
    if (action) {
      event.preventDefault();
      action();
    }
  };

  return (
    <div
      {...rest}
      className={className ? `stepper ${className}` : "stepper"}
      role="spinbutton"
      tabIndex={disabled ? -1 : 0}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      aria-valuenow={current}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-disabled={disabled || undefined}
      onKeyDown={handleKeyDown}
    >
      <button
        type="button"
        className="stepper__button"
        tabIndex={-1}
        aria-label="Decrease"
        disabled={disabled || current <= min}
        onClick={() => set(current - step)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar stepper__bar--h" />
        </span>
      </button>
      <p className="stepper__value" aria-hidden="true">
        {current}
      </p>
      <button
        type="button"
        className="stepper__button"
        tabIndex={-1}
        aria-label="Increase"
        disabled={disabled || current >= max}
        onClick={() => set(current + step)}
      >
        <span className="stepper__icon" aria-hidden="true">
          <span className="stepper__bar stepper__bar--h" />
          <span className="stepper__bar stepper__bar--v" />
        </span>
      </button>
    </div>
  );
}

export default Stepper;

